// The pet's name, filled in when the template is added.
const PET = {{pet}};
// The label and the key turn red once the last feed is this many minutes old.
const DUE = 12 * 60;
const COCOA = '#2b1f14';
const CREAM = '#ffe9cf';
const AMBER = '#ffbe1a';
const RED = '#ff5a5f';
const PAW = 'M3.8 10A2.2 2.8 0 1 0 8.2 10A2.2 2.8 0 1 0 3.8 10Z M7.8 5.8A2.2 2.8 0 1 0 12.2 5.8A2.2 2.8 0 1 0 7.8 5.8Z '
  + 'M12.3 5.8A2.2 2.8 0 1 0 16.7 5.8A2.2 2.8 0 1 0 12.3 5.8Z M16.3 10A2.2 2.8 0 1 0 20.7 10A2.2 2.8 0 1 0 16.3 10Z '
  + 'M12.2 11.2c-3 0-6.2 4.6-6.2 6.8 0 1.8 1.6 2.6 3 2.6 1.3 0 2-.6 3.2-.6s1.9.6 3.2.6c1.4 0 3-.8 3-2.6 0-2.2-3.2-6.8-6.2-6.8z';
// The key: a disc with the check cut out, so the check still shows in tinted and clear mode.
const KEY = 'M24 0A24 24 0 1 0 24 48A24 24 0 1 0 24 0Z M17.77 23.23L21.44 26.89L30.17 17.29A1.8 1.8 0 0 1 32.83 '
  + '19.71L22.83 30.71A1.8 1.8 0 0 1 20.23 30.77L15.23 25.77A1.8 1.8 0 0 1 17.77 23.23Z';

// Clockwise when `hole`, so inside a counterclockwise shape it cuts a hole under the nonzero rule.
function ellipse(cx, cy, rx, ry, hole) {
  const arc = 'A' + rx + ' ' + ry + ' 0 1 ' + (hole ? 1 : 0) + ' ';
  return 'M' + (cx - rx) + ' ' + cy + arc + (cx + rx) + ' ' + cy + arc + (cx - rx) + ' ' + cy + 'Z';
}

// The pet's face is cut out of her head and muzzle rather than drawn in ink on top. In full color the cuts show
// the backdrop, which is the ink; in tinted and clear mode, where every shape takes one color, they still show.
const NOSE = ellipse(32, 35.5, 4, 3, true);
const MOUTH = 'M32.8 39.3L32.8 41A0.8 0.8 0 0 1 31.2 41L31.2 39.3A0.8 0.8 0 0 1 32.8 39.3Z M28.83 41.12L29.68 41.66L30.47 '
  + '42.02L31.24 42.23L32 42.3L32.76 42.23L33.53 42.02L34.32 41.66L35.17 41.12A0.8 0.8 0 0 1 36.03 42.48L35.13 43.05A0.8 '
  + '0.8 0 0 1 35.03 43.1L34.13 43.5A0.8 0.8 0 0 1 34.01 43.55L33.11 43.79A0.8 0.8 0 0 1 32.97 43.82L32.07 43.9A0.8 0.8 0 '
  + '0 1 31.93 43.9L31.03 43.82A0.8 0.8 0 0 1 30.89 43.79L29.99 43.55A0.8 0.8 0 0 1 29.87 43.5L28.97 43.1A0.8 0.8 0 0 1 '
  + '28.87 43.05L27.97 42.48A0.8 0.8 0 0 1 28.83 41.12Z';
const OPEN_EYES = ellipse(24.5, 27, 3, 3, true) + ellipse(39.5, 27, 3, 3, true);
