  + ' 25.91A1 1 0 0 1 27.47 26.02L28.22 26.81A1 1 0 0 1 26.78 28.19L26.08 27.46L25.49 27.02L24.97 26.78L24.5'
  + ' 26.71L24.03 26.78L23.51 27.02L22.92 27.46L22.22 28.19A1 1 0 0 1 20.78 26.81Z M35.78 26.81L36.53 26.02A1 1 0 0 1'
  + ' 36.65 25.91L37.4 25.35A1 1 0 0 1 37.59 25.24L38.34 24.9A1 1 0 0 1 38.6 24.82L39.35 24.71A1 1 0 0 1 39.65'
  + ' 24.71L40.4 24.82A1 1 0 0 1 40.66 24.9L41.41 25.24A1 1 0 0 1 41.6 25.35L42.35 25.91A1 1 0 0 1 42.47 26.02L43.22'
