// The pet herself: eyes up while she waits, shut with her tongue out just after a meal.
function puppy(fed, width) {
  const scale = width / 64;
  const part = (d, paint) => Object.assign({ type: 'path', d, viewBox: [0, 0, 64, 60] }, paint);
  return { type: 'zstack', frame: { width, height: width * 60 / 64 }, children: [
    part('M12 13 C2 17 2 37 11 41 C17 37 19 24 17 14Z M52 13 C62 17 62 37 53 41 C47 37 45 24 47 14Z',
      { fill: '#8a5527' }),
    part(ellipse(32, 30, 20, 19) + (fed ? SHUT_EYES : OPEN_EYES) + NOSE + MOUTH, { fill: '#f2b46b' }),
    part(ellipse(32, 40, 11, 8.5) + NOSE + MOUTH, { fill: '#fff1dc' }),
    !fed && part(ellipse(25.6, 25.8, 1, 1) + ellipse(40.6, 25.8, 1, 1), { fill: '#FFFFFF' }),
    part(ellipse(18.5, 34.5, 3, 2) + ellipse(45.5, 34.5, 3, 2), { fill: '#ff9aa8', opacity: 0.85 }),
    fed && part('M29.6 42.4 q2.4 7 4.8 0z', { fill: '#ff7f8e', stroke: { color: COCOA, width: 1.2 * scale } }),
  ] };
}

function since(minutes) {
  if (minutes < 1) return 'just now';
  if (minutes < 60) return minutes + 'm';
  const rest = minutes % 60;
  return Math.floor(minutes / 60) + 'h ' + (rest < 10 ? '0' : '') + rest + 'm';
}

function render(ctx) {
  // Sizes are in units of `u`, 1/170 of the widget's height. Bricolage's line is 1.2 times its size, so the gaps
  // around the time are 0.1 of its size shorter, as if its line were its size.
  const u = ctx.height / 170;
  const last = ctx.data.last;
  const due = !last || last.minutesAgo >= DUE;
  const tone = due ? RED : AMBER;
  const who = last && (last.by.me ? 'you' : last.by.name || 'someone');

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: COCOA,
    children: [
      { type: 'vstack', align: 'leading', spacing: 0,
        padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: PAW, viewBox: [0, 0, 24, 24], fill: tone, frame: { width: 15 * u, height: 15 * u } },
            { type: 'text', value: PET, size: 13 * u, weight: 'bold', color: tone, lineLimit: 1, minScale: 0.4 } ] },
          { type: 'text', value: last ? since(last.minutesAgo) : 'Not fed', fontName: 'Bricolage Grotesque Display',
            size: 36 * u, kerning: -1.08 * u, color: CREAM, accent: true, lineLimit: 1, minScale: 0.5,
            padding: { top: 4.4 * u } },
          { type: 'text', value: last ? 'fed by ' + who : 'tap after a meal', size: 12.5 * u, weight: 'semibold',
            color: CREAM, opacity: 0.8, lineLimit: 1, minScale: 0.6, padding: { top: 1.4 * u } },
        ] },
      { type: 'zstack', padding: { leading: 8 * u, bottom: 4 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomLeading' },
        children: [puppy(!!last && last.minutesAgo < 30, 74 * u)] },
      last && last.by.me && last.minutesAgo < 60 && { type: 'zstack', padding: { top: 8 * u, trailing: 10 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topTrailing' },
        children: [
          { type: 'button', action: 'undo', rowId: last.id, label: 'Undo', children: [
            { type: 'symbol', name: 'arrow.uturn.backward', size: 12, weight: 'bold', color: CREAM,
              frame: { width: 30, height: 30 }, background: '#ffe9cf22', clip: 'circle' } ] },
        ] },
      { type: 'zstack', padding: 13 * u,
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomTrailing' },
        children: [
          { type: 'button', action: 'feed', label: 'Fed ' + PET, children: [
            { type: 'path', d: KEY, viewBox: [0, 0, 48, 48], fill: tone, accent: true,
              frame: { width: 46 * u, height: 46 * u }, shadow: { color: '#0000004D', radius: 5 * u, y: 4 * u } } ] },
        ] },
    ],
  };
}
